def replace_topic(text, key, body):
    marker = '{k:"' + key + '",'
    start = text.find(marker)
    if start < 0:
        raise AssertionError(f"topic not found: {key}")
    end = text.find('},{k:"', start)
    if end < 0:
        end = text.find('}]};', start)
        if end < 0:
            raise AssertionError(f"topic end not found: {key}")
    return text[:start] + body + text[end:]

